use std::collections::HashSet;
use std::fs;
use std::io::{self, BufRead};
use std::path::{Path, PathBuf};

use anyhow::Result;
use clap::{Arg, ArgAction, Command};
use ignore::WalkBuilder;
use regex::Regex;

// Service-specific patterns that don't require context
const SERVICE_PATTERNS: &[(&str, &str)] = &[
    // GitHub tokens
    ("github_token", r"(ghp|gho|ghu|ghs|ghr)_[A-Za-z0-9_]{36,}"),
    // GitHub PAT
    ("github_pat", r"github_pat_[A-Za-z0-9_]{36,}"),
    // Stripe
    ("stripe_key", r"(sk|rk)_live_[A-Za-z0-9]{24,}"),
    // Twilio SID
    ("twilio_sid", r"SK[a-z0-9]{32}"),
    // Google API key
    ("google_api", r"AIzaSy[A-Za-z0-9_\-]{33}"),
    // Slack tokens
    ("slack_token", r"xox[bapsr o]-\d+(-[a-z0-9]+)+"),
    // JWT tokens
    ("jwt", r"eyJ[A-Za-z0-9_\-]+\.[A-Za-z0-9_\-\.]*"),
    // npm tokens
    ("npm_token", r"npm_[A-Za-z0-9]{36,}"),
    // Private keys
    ("private_key", r"-----BEGIN (RSA |EC |DSA |OPENSSH |PGP )?PRIVATE KEY( BLOCK)?-----"),
];

// Context-based patterns that require a keyword before the value
const CONTEXT_KEYWORDS: &str = r"(?i)(?:password|secret|token|key|apikey)";

// Characters allowed in secret values
const VALUE_CHARS: &str = r"[A-Za-z0-9+/=\._\-~]+";

fn compute_entropy(s: &str) -> f64 {
    if s.is_empty() {
        return 0.0;
    }
    let mut char_counts = std::collections::HashMap::new();
    for c in s.chars() {
        *char_counts.entry(c).or_insert(0u32) += 1;
    }
    let n = s.len() as f64;
    let mut entropy = 0.0;
    for count in char_counts.values() {
        let p = *count as f64 / n;
        entropy -= p * p.log2();
    }
    entropy
}

/// Check if a string has high enough entropy to be considered a secret
fn has_high_entropy(s: &str) -> bool {
    let len = s.len();
    if len < 15 {
        return false;
    }

    // Check base64 entropy (charset: A-Za-z0-9+/=)
    let b64_chars: String = s.chars()
        .filter(|c| c.is_ascii_alphanumeric() || *c == '+' || *c == '/' || *c == '=')
        .collect();
    if b64_chars.len() >= len && compute_entropy(&b64_chars) > 4.5 {
        return true;
    }

    // Check hex entropy (charset: 0-9a-fA-F)
    let hex_chars: String = s.chars()
        .filter(|c| c.is_ascii_hexdigit())
        .collect();
    if hex_chars.len() >= len / 2 && hex_chars.len() >= 10 && compute_entropy(&hex_chars) > 3.0 {
        return true;
    }

    // Check if all uppercase/digits (base32/base36 like)
    let upper_digit_count = s.chars().filter(|c| c.is_ascii_uppercase() || c.is_ascii_digit()).count();
    if upper_digit_count == len {
        // Purely uppercase/digit string - check entropy
        return compute_entropy(s) > 2.8;
    }

    // Check if the string has uppercase+digit run of significant length
    // with sufficient entropy
    let mut max_run_len = 0;
    let mut current_run = String::new();
    for c in s.chars() {
        if c.is_ascii_uppercase() || c.is_ascii_digit() {
            current_run.push(c);
            if current_run.len() > max_run_len {
                max_run_len = current_run.len();
            }
        } else {
            current_run.clear();
        }
    }

    // If no significant uppercase/digit run, check if it's a diverse mixed-case string
    // that would look like a real API key

    false
}

/// Check if the captured group from additional pattern has enough entropy
fn additional_pattern_entropy_check(s: &str) -> bool {
    has_high_entropy(s)
}

struct PatternMatch {
    line_number: usize,
    line: String,
    secret: String,
}

fn find_secrets(
    content: &str,
    service_patterns: &[(Regex, &str)],
    context_pattern: &Regex,
    additional_patterns: &[Regex],
    only_matching: bool,
) -> Vec<PatternMatch> {
    let mut results = Vec::new();
    let mut seen_secrets: HashSet<String> = HashSet::new();

    for (line_idx, line) in content.lines().enumerate() {
        let line_number = line_idx + 1;
        let mut line_secrets: Vec<String> = Vec::new();

        // Check service-specific patterns
        for (pattern, _name) in service_patterns {
            for m in pattern.find_iter(line) {
                let secret = m.as_str().to_string();
                if !line_secrets.contains(&secret) {
                    line_secrets.push(secret);
                }
            }
        }

        // Check context-based pattern
        for cap in context_pattern.captures_iter(line) {
            if let Some(value_match) = cap.get(1) {
                let value = value_match.as_str();
                if value.len() >= 16 && has_high_entropy(value) {
                    if !line_secrets.contains(&value.to_string()) {
                        line_secrets.push(value.to_string());
                    }
                }
            }
        }

        // Check additional patterns
        for pattern in additional_patterns {
            if pattern.captures_len() > 1 {
                // Has capture group - entropy check on captured group
                for cap in pattern.captures_iter(line) {
                    if let Some(group) = cap.get(1) {
                        let s = group.as_str();
                        if additional_pattern_entropy_check(s) {
                            let full_match = cap.get(0).unwrap().as_str();
                            if !line_secrets.contains(&full_match.to_string()) {
                                line_secrets.push(full_match.to_string());
                            }
                        }
                    }
                }
            } else {
                // No capture group - match everything
                for m in pattern.find_iter(line) {
                    let s = m.as_str();
                    if !line_secrets.contains(&s.to_string()) {
                        line_secrets.push(s.to_string());
                    }
                }
            }
        }

        for secret in line_secrets {
            let key = format!("{}:{}", line_number, secret);
            if seen_secrets.insert(key) {
                if only_matching {
                    results.push(PatternMatch {
                        line_number,
                        line: line.to_string(),
                        secret: secret.clone(),
                    });
                } else {
                    // For default mode, only add each line once
                    let line_key = format!("LINE:{}", line_number);
                    if seen_secrets.insert(line_key) {
                        results.push(PatternMatch {
                            line_number,
                            line: line.to_string(),
                            secret: secret.clone(),
                        });
                    }
                }
            }
        }
    }

    results
}

fn should_ignore_file(path: &Path, ignore_patterns: &[glob::Pattern]) -> bool {
    for pattern in ignore_patterns {
        if let Some(filename) = path.file_name() {
            if pattern.matches(&filename.to_string_lossy()) {
                return true;
            }
        }
        if pattern.matches(&path.to_string_lossy()) {
            return true;
        }
    }
    false
}

fn parse_secretsignore(path: &Path) -> (Vec<glob::Pattern>, HashSet<String>) {
    let mut patterns = Vec::new();
    let mut secrets = HashSet::new();

    if let Ok(file) = fs::File::open(path) {
        let reader = io::BufReader::new(file);
        let mut in_secrets_section = false;

        for line in reader.lines() {
            if let Ok(line) = line {
                let trimmed = line.trim();
                if trimmed.starts_with('#') || trimmed.is_empty() {
                    continue;
                }
                if trimmed == "[secrets]" {
                    in_secrets_section = true;
                    continue;
                }
                if trimmed.starts_with('[') {
                    in_secrets_section = false;
                    continue;
                }
                if in_secrets_section {
                    secrets.insert(trimmed.to_string());
                } else {
                    if let Ok(p) = glob::Pattern::new(trimmed) {
                        patterns.push(p);
                    }
                }
            }
        }
    }

